"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["5935"],{6236(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>s,contentTitle:()=>r,toc:()=>d,assets:()=>l});var a=JSON.parse('{"id":"how-to/hardware/essential_getting_started","title":"Getting started with AirPrime HL Essential Modules","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/hardware/essential_getting_started.md","sourceDirName":"how-to/hardware","slug":"/how-to/hardware/essential_getting_started","permalink":"/personal-av-docs/docs/how-to/hardware/essential_getting_started","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/hardware/essential_getting_started.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Getting started with AirPrime HL Essential Modules","sidebar_label":"Getting started with AirPrime HL Essenti","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/howto/hardware/essential_getting_started","format":"md"}}'),o=n(4848),i=n(8453);let s={title:"Getting started with AirPrime HL Essential Modules",sidebar_label:"Getting started with AirPrime HL Essenti",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/howto/hardware/essential_getting_started",format:"md"},r,l={},d=[];function c(e){let t={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:[":::note Edition\n",(0,o.jsx)(t.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(t.a,{href:"https://doc.airvantage.net/av/howto/hardware/essential_getting_started",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsx)(t.p,{children:"Getting started with AirPrime HL Essential Modules\nIf you already have a host processor and you want radio connectivity, you can use an essential module and a library to communicate with AirVantage. It provides all the great device management and application management features supported by your host, it\u2019s really simple to use and it does the job for simple data exchange.\nFollow this tutorial to connect your Essential module with AirVantage.\n1 /\nConnect\n2 /\nCollect\n3 /\nTest\n4 /\nAnalyze\n5 /\nAct\nWhat are the supported devices and modules?\nThe following essential modules are supported:\nHL6xxx / HL8xxx / HL7xxx\nand not supported:\nMC5728 / MC7xxx / MC8xxx / MC9090\nEM73xx\nSL9090\nSL809X\nAR*\nWP*\nAny issues ?\nIf you encounter any issue to set up your device, don\u2019t hesitate to use the\ndeveloper forum\nto benefit from the developer community experience.\nStep 1: Connect your device to AirVantage\nThese modules don\u2019t include any Application Framework. You need to integrate a connector in your host application to enable the connection with AirVantage.\nCreate an account\nRegister for an AirVantage Platform\naccount\n.\nYou will receive an email when your account is up.\nRegister your system\nWhat is a system?\nA system represents:\nA module which supplies the connectivity\nA SIM card which give the network access (if any)\nSome applications running in the hardware (any host such as micro controller or processor)\nGo to Register activity\nClick on the \u201CAirPrime HL Series\u201D section\nSelect your HL series module\nFill the serial number and IMEI fields\nSet a name and click on Register\nOn the module side, follow the right help panel to set a communication policy and create a communication.\nIn the list, when the module is synchronized (the synchronization icon is green), select the newly created system and click on the \u201CMonitor\u201D icon\nHow to find Serial Number and IMEI\nTo get these two information, open a serial port terminal (like Tera Term, \u2026) and send the following AT commands:\nFor the IMEI:\nat+kgsn=1\n+KGSN: 3595150503142506\nNote: For HL6 and HL78, use AT+CGSN at command instead.\nFor the Serial Number:\nat+kgsn=3\n+KGSN: HD513700430510\nHow to open a session with AirVantage\nTo start a session with AirVantage, open a serial port terminal (like Tera Term, \u2026) and send the following AT commands:\nat+wdss=0,\u201Cyour_apn\u201D\nOK\nat+wdss=1,1\nOK\nIf you get any ERROR, check the AT Commands guide for your module.\nCheck the connection\nGo on Monitor Activity > Systems\nSelect your system and display the System detail\nClick on the Configure Communication button on the top of the page\nToggle on the Heartbeat check and click on the Ok button in the dialog box\nOn the top of the page, the communication status will be updated\nManage your device\nAlthough it\u2019s optional, it\u2019s useful to synchronize your device with AirVantage at least once to check if configuration is correct.\nHave a look\nhere\nto learn how to synchronize your system and how to use the Device Management Features.\nStep 2: Design your application\nIn this step, we are going to send data using the MQTT API for devices. A huge choice of libraries for a large set of hardware and languages is available on the web. Choose the one best suited to your hardware.\nYou can use\nREST API for devices\nas well. As soon as you have an IP stack and the capability to do HTTP calls, you can use our HTTP API for devices.\nIt doesn\u2019t give you all the fancy device management and application management features but it\u2019s really simple to use and it does the job for simple data exchange. Read the following\narticle\nto learn how to use the REST API for devices to easily enable the communication with AirVantage from your embedded application.\nYou\u2019re ready to implement your embedded application on:\nRasberryPI\n, or\nUbuntu PC\nor any\nLinux platform\n:\nfollow this\ntutorial\nusing HL Development Kit to communicate with AirVantage\nArduino\n:\nfollow this\ntutorial\nusing Arduino Mega + HL Shield to communicate with AirVantage\nStep 3: Test your application\nFinally test your application by using this\ntutorial\n.\nStep 4: Define a dashboard and rules\nOnce your system communicates correctly and data values are stored in AirVantage, you may want to automate the analysis by using rules and display it in a dashboard. Have a look at this\ntutorial\nto learn how to define a rule and design your operational dashboard.\nStep 5: Use the API\nNow you checked and visualize your data, you may want to use them in your specific application. Have a look at our\nAirVantage API\nto learn how to use this API to build powerful applications.\nSample code\nGreenhouse\nThis sample (used in the above steps) publishes emulated Temperature and Humidity to AirVantage, and receives the \u201CTurnOn\u201D command from AirVantage.\nYou may adapt this code to fit your needs.\nMQTT Spooler\nThis app automatically converts CVS data to MQTT messages prior publishing to server. It also automatically converts incoming MQTT messages (pertaining to a subscribed Topic) to CSV data. This app could be reused as a quick integration option (no need to deal with MQTT code) with your existing sensor/actuator based application."})]})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},8453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var a=n(6540);let o={},i=a.createContext(o);function s(e){let t=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),a.createElement(i.Provider,{value:t},e.children)}}}]);